import{_ as n,l,o as a,b as p,d as t,m as i,q as d}from"./chunks/framework.Tf23FRXt.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"九宫幻卡","slug":"九宫幻卡","link":"#九宫幻卡","children":[{"level":3,"title":"基本玩法","slug":"基本玩法","link":"#基本玩法","children":[]},{"level":3,"title":"特殊规则","slug":"特殊规则","link":"#特殊规则","children":[]},{"level":3,"title":"成长规划","slug":"成长规划","link":"#成长规划","children":[]}]}],"relativePath":"topic/triple-triad.htm.md","filePath":"topic/triple-triad.md","lastUpdated":1791098838000}'),o={name:"topic/triple-triad.htm.md"};function s(_,e,f,m,h,u){const r=l("UnderConstruction");return a(),p("div",null,[e[0]||(e[0]=t("h2",{id:"九宫幻卡",tabindex:"-1"},"九宫幻卡",-1)),e[1]||(e[1]=t("p",null,"九宫幻卡是来自 FF8 的一种策略型卡牌游戏，基础规则是比较卡牌临边大小，若己方数字大于对方数字，则可以将对方的卡牌翻过来。",-1)),e[2]||(e[2]=t("h3",{id:"基本玩法",tabindex:"-1"},"基本玩法",-1)),i(r),e[3]||(e[3]=t("h3",{id:"特殊规则",tabindex:"-1"},"特殊规则",-1)),i(r),e[4]||(e[4]=d('<h3 id="成长规划" tabindex="-1">成长规划</h3><p>解锁幻卡功能之后，首先去幻卡广场，把广场上的几位大哥都殴打到掉卡，其中最里面的幻卡王可使用攻略：<a href="https://bbs.nga.cn/read.php?tid=15688531" target="_blank" rel="noreferrer">论殴打幻卡王的 55 种姿势</a>)、<a href="https://bbs.nga.cn/read.php?tid=8462015" target="_blank" rel="noreferrer">新手 5 卡先手 95% 胜幻卡王拿巴哈姆特卡打法</a>)</p><p>把金碟游乐场广场几位大师的幻卡全拿到之后，要开始解锁卡组，由于卡组限制与获得的卡牌数量有关，因此玩家的第一个目标是集齐 60 张卡牌，解锁 4 张 3 星 + 1 张 5 星的卡组许可：</p><p>把刷巴哈拿到的废卡全部卖掉，然后把青铜包开完，能刷副本掉的尽量刷副本 (多余的卡牌记得拿来卖)</p><p><a href="https://ff14.huijiwiki.com/wiki/%E4%B9%9D%E5%AE%AB%E5%B9%BB%E5%8D%A1%E5%8D%A1%E7%89%8C" target="_blank" rel="noreferrer">幻卡列表</a>中的一星和二星卡的掉率相对都是比较高的，还有像苔小妖这样的幻卡只能通过购买获得 (就早点买下)，仅 1~2 星所有卡牌加起来就有 88 张，等解锁了 60 张卡牌就可以组高位卡组了。</p><p>通常来说和 NPC 对战的对战费 (以及获胜给所给的金碟币) 一定程度上反映了这个 NPC 的难度，常见的策略比如等地区流行规则切换为逆转时，用低星卡组翻盘，或者是打天选 / 混乱这种赌脸玩法。</p>',6))])}const k=n(o,[["render",s]]);export{c as __pageData,k as default};
